using System.Text;
using Microsoft.EntityFrameworkCore;
using MyThuat.Api.Data;
namespace MyThuat.Api.Services;
public static class MainDataReport
{
    public static async Task Save(MyThuatDbContext db,string root){
        var accounts=await db.TaiKhoan.AsNoTracking().Include(x=>x.ThanhVien).Include(x=>x.GiaoVien).Where(x=>x.ThanhVien!=null&&x.ThanhVien.MaThanhVien.StartsWith("MAIN_")||x.GiaoVien!=null&&x.GiaoVien.MaGiaoVien.StartsWith("MAIN_")||x.TenDangNhap=="hocvu01"||x.TenDangNhap=="thungan01"||x.TenDangNhap=="kho01"||x.TenDangNhap=="quantri01").OrderBy(x=>x.TenDangNhap).ToListAsync();
        var report=new StringBuilder("# Database chính — hướng dẫn thử\n\nDữ liệu giả lập lưu thật trong SQL Server, không phải dữ liệu cá nhân/giao dịch thật.\n\nMật khẩu khởi tạo tài khoản mẫu mới: `"+MainData.Password+"`. Đổi mật khẩu trước khi vận hành công khai. Không thay đổi tài khoản cũ.\n\n| Tên đăng nhập | Họ tên | Mật khẩu khởi tạo | Vai trò |\n|---|---|---|---|\n");
        foreach(var a in accounts)report.AppendLine($"| {a.TenDangNhap} | {a.ThanhVien?.HoTen??a.GiaoVien?.HoTen??a.HoTenNhanVien} | `{MainData.Password}` | {a.VaiTroChinh} |");
        report.AppendLine("\n## Thử nhanh\n- hv01: bản thân + nhiều hồ sơ con; nhiều đăng ký, lịch học, tư vấn.\n- hv17: chưa thanh toán. hv18: thanh toán một phần. hv19: chưa có lớp. hv20: chưa tạo hồ sơ.\n- gv01: có lớp. gv08: chưa phân lớp.\n- hocvu01: mở /ho-tro để tiếp nhận, đọc, trả lời tư vấn.\n- thungan01 và kho01: dùng API/WinForms theo quyền.\n\n## Các lớp\n| Mã | Tên | Ngày bắt đầu–kết thúc | Trạng thái | Chỗ đã giữ / tối đa |\n|---|---|---|---|---|");
        var classes=await db.LopHoc.AsNoTracking().Where(x=>x.MaLop.StartsWith("MAIN_")).OrderBy(x=>x.MaLop).ToListAsync();foreach(var c in classes){var occupied=await db.DangKy.CountAsync(x=>x.LopHocId==c.Id&&(x.TrangThai=="DA_XAC_NHAN"||(x.TrangThai=="CHO_THANH_TOAN"||x.TrangThai=="CHO_CHUYEN")&&x.HanGiuCho>BusinessClock.Now));report.AppendLine($"| {c.MaLop} | {c.TenLop} | {c.NgayKhaiGiangDuKien:dd/MM/yyyy}–{c.NgayKetThucDuKien:dd/MM/yyyy} | {c.TrangThai} | {occupied}/{c.SiSoToiDa} |");}
        var mainStudents=await db.HocVien.CountAsync(x=>x.MaHocVien.StartsWith("MAIN_"));
        var mainRegistrations=await db.DangKy.AsNoTracking().Include(x=>x.HoSoTheoHoc).Where(x=>x.MaDangKy.StartsWith("MAIN_DK")).ToListAsync();
        var active=mainRegistrations.Where(x=>x.TrangThai=="DA_XAC_NHAN"||((x.TrangThai=="CHO_THANH_TOAN"||x.TrangThai=="CHO_CHUYEN")&&x.HanGiuCho>BusinessClock.Now)).ToList();
        report.AppendLine($"\n## Đối chiếu học viên và chỗ\n- Hồ sơ học viên mới: {mainStudents}.\n- Tổng đăng ký mới: {mainRegistrations.Count}; đăng ký đang tính giữ chỗ: {active.Count}; học viên phân biệt đang có chỗ: {active.Select(x=>x.HoSoTheoHoc!.HocVienId).Distinct().Count()}.\n- Một học viên có thể có nhiều đăng ký ở các lớp khác lịch; không so tổng hồ sơ với tổng chỗ của các lớp.\n- Chỗ đang chiếm = đã xác nhận + chờ thanh toán/chờ chuyển còn hạn. Hủy, hết hạn không giữ chỗ. Lớp đã kết thúc vẫn giữ lịch sử đăng ký nhưng không tính vào khả năng tuyển sinh lớp đang mở.\n- Bảng phía trên là số liệu lúc xuất; mở web sẽ tính lại theo trạng thái và thời hạn thực tế.\n- Mật khẩu trong bảng là mật khẩu khởi tạo; nếu đã đổi, dùng mật khẩu mới. DB chỉ lưu hash, không đọc lại mật khẩu thật để đưa vào báo cáo.\n");
        report.AppendLine("\n## Mã giảm\n| Mã | Nhóm | Loại | Giá trị | Trần | Khóa áp dụng | Hạn |\n|---|---|---|---|---|---|---|");var codes=new[]{"JUNIOR10","MAUNUOC200","BUIMOI15","BUICHUNG5","DAHETHAN","HETLUOT","HOACU10"};foreach(var p in await db.KhuyenMai.AsNoTracking().Include(x=>x.KhoaApDung).Where(x=>codes.Contains(x.MaKhuyenMai)).ToListAsync())report.AppendLine($"| {p.MaKhuyenMai} | {p.NhomKhoanThu} | {p.LoaiGiam} | {p.GiaTriGiam:N0} | {p.TranGiam:N0} | {p.KhoaApDung?.TenKhoa??"Mọi khóa"} | {p.KetThuc:dd/MM/yyyy HH:mm} |");
        report.AppendLine("\nBUIMOI15 dành thành viên được xác nhận trong 7 ngày; HETLUOT đã sử dụng hết; DAHETHAN đã hết hạn. Thử JUNIOR10 ở MAIN_L13 (lớp còn chỗ), MAUNUOC200 ở MAIN_L06.\n\nKho có 24 SKU, phiếu nhập/xuất/cấp/trả/hỏng/dự trữ; không nhập tay số tồn. Giá, đơn vị cung cấp và hình hồ sơ là minh họa.\n\nNgày và hạn giữ chỗ không tự dời khi mở web; các phiếu chưa trả sẽ hết hạn đúng quy định. Không tự xác nhận chuyển khoản từ web. Thanh toán đang theo luồng thu ngân đối chiếu, chưa có cổng thanh toán.\n\nTư vấn: khách gửi và nhận mã + khóa riêng. Thành viên đăng nhập xem được yêu cầu của mình. Khóa mẫu lưu riêng tại MAIN_TAI_KHOAN.md, không công khai.\n\nXem docs/main-database.md để biết API, cách sao lưu/nâng cấp và các việc còn cần trước khi vận hành thật. Chưa tạo thêm màn hình WinForms hoặc trình soạn bài viết trực quan; các API đã cung cấp để tích hợp.\n");
        await File.WriteAllTextAsync(Path.Combine(root,".local","MAIN_HUONG_DAN.md"),report.ToString());Console.WriteLine("Hướng dẫn hiện tại: .local/MAIN_HUONG_DAN.md");
    }
}
